export function translate(language: Language, source: string): string {
  if (language === "ru") return source;
  return supplemental[language][source] ?? translations[language][source] ?? source;
}

export function loadLanguage(): Language {
  try {
    const saved = localStorage.getItem("blau-language");
    return saved && isLanguage(saved)
      ? saved
      : "ru";
  } catch {
    return "ru";
  }
}
